-- webhook
DO $authz$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'webhook' LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, 'webhook');
  END LOOP;
END
$authz$;
ALTER TABLE public."webhook" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "SELECT" ON "public"."webhook" FOR SELECT USING ("companyId" = ANY ((SELECT get_companies_with_any_employee_permission(ARRAY['settings.billing_view', 'settings.company_view', 'settings.companies_view', 'settings.documentTemplates_view', 'settings.logos_view', 'settings.printing_view', 'settings.accounting_view', 'settings.inventory_view', 'settings.invoicing_view', 'settings.items_view', 'settings.people_view', 'settings.planning_view', 'settings.purchasing_view', 'settings.production_view', 'settings.projects_view', 'settings.time_view', 'settings.service_view', 'settings.quality_view', 'settings.sales_view', 'settings.resources_view', 'settings.apiKeys_view', 'settings.approvalRules_view', 'settings.auditLogs_view', 'settings.backups_view', 'settings.customFields_view', 'settings.demoData_view', 'settings.integrations_view', 'settings.itarCertifications_view', 'settings.security_view', 'settings.sequences_view', 'settings.serialNumbers_view', 'settings.webhooks_view']::text[]))::text[]));
CREATE POLICY "INSERT" ON "public"."webhook" FOR INSERT WITH CHECK ("companyId" = ANY ((SELECT get_companies_with_employee_permission('settings.webhooks_create'))::text[]));
CREATE POLICY "UPDATE" ON "public"."webhook" FOR UPDATE USING ("companyId" = ANY ((SELECT get_companies_with_employee_permission('settings.webhooks_update'))::text[]));
CREATE POLICY "DELETE" ON "public"."webhook" FOR DELETE USING ("companyId" = ANY ((SELECT get_companies_with_employee_permission('settings.webhooks_delete'))::text[]));
